mat2 rot(float a) { float s = sin(a), c = cos(a); return mat2(c, -s, s, c); }
float map(vec3 p) {
  p.xz = rot(time * 0.3) * p.xz;
  float sphere = length(p) - 1.1;
  float bumps = sin(p.x * 4.0) * sin(p.y * 4.0) * sin(p.z * 4.0) * 0.15;
  return sphere + bumps;
}
shader_body {
  vec2 p = (uv - 0.5) * vec2(aspect.x, 1.0) * 2.0;
  vec3 ro = vec3(0.0, 0.0, -3.0);
  vec3 rd = normalize(vec3(p, 1.6));
  float t = 0.0;
  for (int i = 0; i < 48; i++) {
    float d = map(ro + rd * t);
    if (d < 0.003 || t > 7.0) break;
    t += d * 0.8;
  }
  vec3 col = vec3(0.03, 0.04, 0.06);
  if (t < 7.0) {
    vec3 pos = ro + rd * t;
    vec2 e = vec2(0.004, 0.0);
    vec3 n = normalize(vec3(
      map(pos + e.xyy) - map(pos - e.xyy),
      map(pos + e.yxy) - map(pos - e.yxy),
      map(pos + e.yyx) - map(pos - e.yyx)
    ));
    vec3 opal = 0.5 + 0.5 * sin(vec3(0.0, 1.0, 2.0) + dot(n, -rd) * 8.0 + time * 2.0);
    col = vec3(0.8, 0.85, 0.9) * 0.6 + opal * 0.8;
  }
  ret = col;
}
